/// Generated protobuf types for the VG (Variation Graph) format.
pub mod vg {
    // prost derives `PartialEq` on every message but cannot derive `Eq` on
    // those holding floats, so it never derives `Eq`; the code is generated.
    #![allow(clippy::derive_partial_eq_without_eq)]
    include!(concat!(env!("OUT_DIR"), "/vg.rs"));
}

/// The subset of [`vg`] the VG parser decodes (see `proto/vg_read.proto`).
pub mod vg_read {
    // Generated by prost like [`vg`]; see the note there.
    #![allow(clippy::derive_partial_eq_without_eq)]
    include!(concat!(env!("OUT_DIR"), "/vg_read.rs"));
}
